CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'viewer',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vehicles(id INTEGER PRIMARY KEY,title TEXT NOT NULL,make TEXT NOT NULL,model TEXT NOT NULL,year INTEGER NOT NULL,price REAL NOT NULL,location TEXT,mileage INTEGER DEFAULT 0,transmission TEXT,fuel TEXT,engine TEXT,body_type TEXT,color TEXT,condition TEXT,status TEXT NOT NULL DEFAULT 'Draft',label TEXT,description TEXT,highlights TEXT,notes TEXT,featured INTEGER DEFAULT 0,views INTEGER DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media(id INTEGER PRIMARY KEY,vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,type TEXT NOT NULL,category TEXT,path TEXT NOT NULL,is_primary INTEGER DEFAULT 0,sort_order INTEGER DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY,name TEXT,phone TEXT,email TEXT UNIQUE,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS enquiries(id INTEGER PRIMARY KEY,vehicle_id INTEGER REFERENCES vehicles(id) ON DELETE SET NULL,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,contact_method TEXT,message TEXT,status TEXT NOT NULL DEFAULT 'New',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inspections(id INTEGER PRIMARY KEY,vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,name TEXT NOT NULL,phone TEXT NOT NULL,preferred_date TEXT,preferred_time TEXT,contact_method TEXT,notes TEXT,status TEXT NOT NULL DEFAULT 'Pending',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS favourites(id INTEGER PRIMARY KEY,customer_key TEXT NOT NULL,vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,created_at TEXT NOT NULL,UNIQUE(customer_key,vehicle_id));
CREATE TABLE IF NOT EXISTS alerts(id INTEGER PRIMARY KEY,name TEXT,phone TEXT,email TEXT,criteria TEXT,status TEXT DEFAULT 'Active',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS car_requests(id INTEGER PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,make TEXT,model TEXT,budget REAL,body_type TEXT,transmission TEXT,condition TEXT,notes TEXT,status TEXT DEFAULT 'New',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,action TEXT,entity TEXT,entity_id TEXT,details TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT,updated_at TEXT);
CREATE INDEX IF NOT EXISTS idx_vehicle_status ON vehicles(status);CREATE INDEX IF NOT EXISTS idx_vehicle_make ON vehicles(make);CREATE INDEX IF NOT EXISTS idx_enquiry_vehicle ON enquiries(vehicle_id);CREATE INDEX IF NOT EXISTS idx_inspection_vehicle ON inspections(vehicle_id);
CREATE TABLE IF NOT EXISTS contact_messages(id INTEGER PRIMARY KEY,name TEXT NOT NULL,phone TEXT,email TEXT,message TEXT NOT NULL,status TEXT DEFAULT 'New',created_at TEXT NOT NULL);
